-- Up Migration

-- Conventions: snake_case, timestamptz, UUIDv7 primary keys generated by the application,
-- money as bigint micro-dollars. Accounting tables never cascade deletes.

-- Dashboard users (ADR 007). Emails are stored lowercased.
CREATE TABLE users (
  id uuid PRIMARY KEY,
  email text NOT NULL UNIQUE CHECK (email = lower(email) AND email LIKE '_%@_%'),
  password_hash text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  disabled_at timestamptz
);

-- Admin sessions: only the SHA-256 of the cookie token is stored.
CREATE TABLE user_sessions (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  token_hash bytea NOT NULL UNIQUE CHECK (length(token_hash) = 32),
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL
);
CREATE INDEX user_sessions_user_id_idx ON user_sessions (user_id);

CREATE TABLE projects (
  id uuid PRIMARY KEY,
  name text NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
  -- Logical model names this project may call. NULL allows every configured model.
  allowed_models text[],
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE project_members (
  project_id uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  role text NOT NULL CHECK (role IN ('owner', 'admin', 'viewer')),
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (project_id, user_id)
);
CREATE INDEX project_members_user_id_idx ON project_members (user_id);

-- API keys (ADR 006): `gw_<key_id>_<secret>`; only HMAC-SHA256(secret, pepper) is stored.
CREATE TABLE api_keys (
  id uuid PRIMARY KEY,
  project_id uuid NOT NULL REFERENCES projects (id),
  key_id text NOT NULL UNIQUE CHECK (key_id ~ '^[0-9a-f]{16}$'),
  secret_hash bytea NOT NULL CHECK (length(secret_hash) = 32),
  name text NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
  created_by uuid REFERENCES users (id),
  created_at timestamptz NOT NULL DEFAULT now(),
  -- Set when the key is rotated: the old key keeps working until then.
  expires_at timestamptz,
  revoked_at timestamptz,
  rotated_to uuid REFERENCES api_keys (id)
);
CREATE INDEX api_keys_project_id_idx ON api_keys (project_id, id DESC);

-- Deployments and routing policies live in config/models.json until the dashboard edits them.
CREATE TABLE model_deployments (
  id uuid PRIMARY KEY,
  name text NOT NULL UNIQUE,
  provider text NOT NULL CHECK (provider IN ('mock', 'ollama', 'openai-compatible')),
  provider_model text NOT NULL,
  base_url text,
  settings jsonb NOT NULL DEFAULT '{}',
  enabled boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE routing_policies (
  id uuid PRIMARY KEY,
  -- NULL: the default for projects without their own policy.
  project_id uuid REFERENCES projects (id) ON DELETE CASCADE,
  model text NOT NULL,
  strategy text NOT NULL CHECK (strategy IN ('priority', 'weighted', 'lowest_latency', 'cost_aware')),
  targets jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE NULLS NOT DISTINCT (project_id, model)
);

-- Versioned prices (ADR 016). A row never changes once written: a price change is a new row with
-- a later effective_from, and each usage row keeps the id of the version it was costed with.
CREATE TABLE model_prices (
  id uuid PRIMARY KEY,
  provider text NOT NULL,
  model text NOT NULL,
  input_micro_usd_per_mtok bigint NOT NULL CHECK (input_micro_usd_per_mtok >= 0),
  output_micro_usd_per_mtok bigint NOT NULL CHECK (output_micro_usd_per_mtok >= 0),
  effective_from timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (provider, model, effective_from)
);

CREATE FUNCTION model_prices_reject_update() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'model_prices rows are immutable: insert a new version instead';
END;
$$;
CREATE TRIGGER model_prices_immutable BEFORE UPDATE ON model_prices
  FOR EACH ROW EXECUTE FUNCTION model_prices_reject_update();

-- One row per logical request; the id is the request ID generated at ingress.
CREATE TABLE request_records (
  id uuid PRIMARY KEY,
  project_id uuid NOT NULL REFERENCES projects (id),
  api_key_id uuid REFERENCES api_keys (id),
  model text NOT NULL,
  deployment text,
  stream boolean NOT NULL,
  status text NOT NULL CHECK (status IN ('success', 'error', 'canceled', 'rejected')),
  http_status smallint NOT NULL,
  error_code text,
  attempt_count smallint NOT NULL CHECK (attempt_count >= 0),
  started_at timestamptz NOT NULL,
  completed_at timestamptz NOT NULL,
  latency_ms integer NOT NULL CHECK (latency_ms >= 0),
  ttft_ms integer CHECK (ttft_ms >= 0),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX request_records_project_started_idx ON request_records (project_id, started_at DESC, id DESC);

-- One row per upstream try; the id is the attemptId in the logs.
CREATE TABLE provider_attempts (
  id uuid PRIMARY KEY,
  request_id uuid NOT NULL REFERENCES request_records (id),
  attempt_number smallint NOT NULL CHECK (attempt_number >= 1),
  deployment text NOT NULL,
  provider text NOT NULL,
  provider_model text NOT NULL,
  routing_policy text,
  routing_reason text,
  outcome text NOT NULL,
  upstream_status smallint,
  started_at timestamptz NOT NULL,
  completed_at timestamptz NOT NULL,
  latency_ms integer NOT NULL CHECK (latency_ms >= 0),
  ttft_ms integer CHECK (ttft_ms >= 0),
  UNIQUE (request_id, attempt_number)
);

-- The usage ledger (ADR 014): UNIQUE(event_id) plus ON CONFLICT DO NOTHING makes at-least-once
-- delivery count each request once.
CREATE TABLE usage_events (
  id uuid PRIMARY KEY,
  event_id uuid NOT NULL UNIQUE,
  request_id uuid NOT NULL UNIQUE REFERENCES request_records (id),
  project_id uuid NOT NULL REFERENCES projects (id),
  api_key_id uuid REFERENCES api_keys (id),
  deployment text,
  provider text,
  provider_model text,
  prompt_tokens integer CHECK (prompt_tokens >= 0),
  completion_tokens integer CHECK (completion_tokens >= 0),
  total_tokens integer CHECK (total_tokens >= 0),
  usage_source text NOT NULL CHECK (usage_source IN ('reported', 'estimated', 'missing')),
  cost_micro_usd bigint CHECK (cost_micro_usd >= 0),
  price_id uuid REFERENCES model_prices (id),
  occurred_at timestamptz NOT NULL,
  ingested_at timestamptz NOT NULL DEFAULT now(),
  CHECK ((usage_source = 'missing') = (total_tokens IS NULL))
);
CREATE INDEX usage_events_project_occurred_idx ON usage_events (project_id, occurred_at DESC);

-- Budgets (ADR 009): reservations are taken in Redis and audited here.
CREATE TABLE budget_periods (
  id uuid PRIMARY KEY,
  project_id uuid NOT NULL REFERENCES projects (id),
  period_start timestamptz NOT NULL,
  period_end timestamptz NOT NULL,
  limit_micro_usd bigint NOT NULL CHECK (limit_micro_usd >= 0),
  spent_micro_usd bigint NOT NULL DEFAULT 0 CHECK (spent_micro_usd >= 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (period_end > period_start),
  UNIQUE (project_id, period_start)
);

CREATE TABLE budget_reservations (
  id uuid PRIMARY KEY,
  budget_period_id uuid NOT NULL REFERENCES budget_periods (id),
  project_id uuid NOT NULL REFERENCES projects (id),
  request_id uuid NOT NULL UNIQUE,
  reserved_micro_usd bigint NOT NULL CHECK (reserved_micro_usd >= 0),
  actual_micro_usd bigint CHECK (actual_micro_usd >= 0),
  status text NOT NULL CHECK (status IN ('reserved', 'reconciled', 'expired')),
  created_at timestamptz NOT NULL DEFAULT now(),
  settled_at timestamptz
);
CREATE INDEX budget_reservations_open_idx ON budget_reservations (created_at) WHERE status = 'reserved';

-- Circuit-breaker transitions and health checks (ADR 012).
CREATE TABLE provider_health_events (
  id uuid PRIMARY KEY,
  deployment text NOT NULL,
  instance_id text NOT NULL,
  from_state text CHECK (from_state IN ('closed', 'open', 'half_open')),
  to_state text NOT NULL CHECK (to_state IN ('closed', 'open', 'half_open')),
  reason text,
  occurred_at timestamptz NOT NULL
);
CREATE INDEX provider_health_events_deployment_idx ON provider_health_events (deployment, occurred_at DESC);

-- One row per admin change, written in the same transaction as the change.
CREATE TABLE audit_logs (
  id uuid PRIMARY KEY,
  project_id uuid REFERENCES projects (id),
  actor_type text NOT NULL CHECK (actor_type IN ('user', 'system')),
  actor_user_id uuid REFERENCES users (id),
  action text NOT NULL,
  target_type text NOT NULL,
  target_id text,
  details jsonb NOT NULL DEFAULT '{}',
  request_id text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK ((actor_type = 'user') = (actor_user_id IS NOT NULL))
);
CREATE INDEX audit_logs_project_idx ON audit_logs (project_id, id DESC);

-- Events the worker gave up on (dead-letter), kept for inspection and replay.
CREATE TABLE failed_events (
  id uuid PRIMARY KEY,
  stream text NOT NULL,
  stream_message_id text NOT NULL,
  event_id uuid,
  payload text NOT NULL,
  error text NOT NULL,
  delivery_count integer NOT NULL,
  failed_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (stream, stream_message_id)
);

-- Down Migration

DROP TABLE failed_events;
DROP TABLE audit_logs;
DROP TABLE provider_health_events;
DROP TABLE budget_reservations;
DROP TABLE budget_periods;
DROP TABLE usage_events;
DROP TABLE provider_attempts;
DROP TABLE request_records;
DROP TRIGGER model_prices_immutable ON model_prices;
DROP FUNCTION model_prices_reject_update();
DROP TABLE model_prices;
DROP TABLE routing_policies;
DROP TABLE model_deployments;
DROP TABLE api_keys;
DROP TABLE project_members;
DROP TABLE projects;
DROP TABLE user_sessions;
DROP TABLE users;
